#include <string.h>
#include "chafa.h"

/* Valid symbol class names from chafa documentation */
static const char *const symbol_classes[] = {
    "all", "alnum", "alpha", "ambiguous",
    "ascii", "bad", "block", "border",
    "braille", "diagonal", "digit", "dot",
    "extra", "geometric", "half", "hhalf",
    "imported", "inverted", "latin", "legacy",
    "narrow", "none", "quad", "sextant",
    "solid", "space", "stipple", "technical",
    "ugly", "vhalf", "wedge", "wide",
    NULL
};

int is_valid_symbol_class(const char *s)
{
    for (int i = 0; symbol_classes[i]; i++) {
        if (strcmp(s, symbol_classes[i]) == 0) return 1;
    }
    return 0;
}

/* Parse a symbol spec like "block+border-diagonal" or "all-wide".
 * Returns 0 on success, else sets *errtag to the offending tag and returns -1.
 * *errtag points into a static buffer. */
static char err_tag_buf[128];

int parse_symbol_spec(const char *spec, const char **errtag)
{
    if (spec == NULL || *spec == '\0') {
        *errtag = "";
        return -1;
    }
    const char *p = spec;
    /* First token may have no leading + or -, treated as + */
    while (*p) {
        /* Skip optional sign */
        if (*p == '+' || *p == '-') p++;
        /* Read tag */
        const char *start = p;
        while (*p && *p != '+' && *p != '-') p++;
        size_t len = (size_t)(p - start);
        if (len == 0) {
            *errtag = "";
            return -1;
        }
        if (len >= sizeof(err_tag_buf)) len = sizeof(err_tag_buf) - 1;
        memcpy(err_tag_buf, start, len);
        err_tag_buf[len] = '\0';
        if (!is_valid_symbol_class(err_tag_buf)) {
            *errtag = err_tag_buf;
            return -1;
        }
    }
    return 0;
}
