static void opts_init(Options *o)
{
    memset(o, 0, sizeof(*o));
    o->optimize = 5;
    o->relative = 0;
    o->polite = 0;
    o->font_ratio = 0.5;
    o->margin_bottom = 1;
    o->margin_right = 0;
    o->scale = 1.0;
    o->animate = 1;
    o->dither_grain_w = 4;
    o->dither_grain_h = 4;
    o->dither_intensity = 1.0;
    o->preprocess = -1;
    o->threshold = 0.5;
    o->threads = -1;
    o->work = 5;
}

/* Matches: --name=value, --name value, -x value, -xvalue. */
static int take_value(int argc, char **argv, int *ip, const char *optname_for_error,
                      const char *eq, const char **out_value)
{
    if (eq) {
        *out_value = eq;
        return 1;
    }
    int i = *ip;
    if (i + 1 >= argc) {
        errmsg("Missing argument for %s", optname_for_error);
        return 0;
    }
    *out_value = argv[i + 1];
    (*ip)++;
    return 1;
}

static int parse_colors_mode(const char *s)
{
    if (!strcmp(s, "none") || !strcmp(s, "2") || !strcmp(s, "8")
        || !strcmp(s, "16/8") || !strcmp(s, "16") || !strcmp(s, "240")
        || !strcmp(s, "256") || !strcmp(s, "full")) return 1;
    return 0;
}

/* Align parser */
static int parse_align_token(const char *tok, int is_first, Options *o)
{
    /* horizontal: left, center, right */
    /* vertical: top, middle/mid, bottom */
    /* aliases: h: l, c, r, mid, etc; v: top, mid, bottom */
    if (!strcmp(tok, "left") || !strcmp(tok, "right") || !strcmp(tok, "center") || !strcmp(tok, "centre")) {
        if (o->align_h) return -2; /* duplicate horizontal */
        o->align_h = tok;
        return 0;
    }
    if (!strcmp(tok, "top") || !strcmp(tok, "bottom") || !strcmp(tok, "mid") || !strcmp(tok, "middle")) {
        if (o->align_v) return -2;
        o->align_v = tok;
        return 0;
    }
    return -1;
}

/* Try to detect magic for supported file formats */
static int detect_format(const char *path)
{
    FILE *fp = fopen(path, "rb");
    if (!fp) return -1;
    unsigned char buf[16];
    size_t n = fread(buf, 1, sizeof(buf), fp);
    fclose(fp);
    if (n >= 8 && buf[0] == 0x89 && buf[1] == 'P' && buf[2] == 'N' && buf[3] == 'G'
        && buf[4] == 0x0D && buf[5] == 0x0A && buf[6] == 0x1A && buf[7] == 0x0A) return 1; /* PNG */
    if (n >= 3 && buf[0] == 0xFF && buf[1] == 0xD8 && buf[2] == 0xFF) return 2; /* JPEG */
    if (n >= 6 && (memcmp(buf, "GIF87a", 6) == 0 || memcmp(buf, "GIF89a", 6) == 0)) return 3; /* GIF */
    if (n >= 4 && memcmp(buf, "qoif", 4) == 0) return 4; /* QOI */
    if (n >= 4 && (memcmp(buf, "II*\0", 4) == 0 || memcmp(buf, "MM\0*", 4) == 0)) return 5; /* TIFF */
    if (n >= 12 && memcmp(buf, "RIFF", 4) == 0 && memcmp(buf + 8, "WEBP", 4) == 0) return 6; /* WebP */
    /* XWD: first 4 bytes are size in BE, then pixmap format. We'll just accept a very tame heuristic */
    if (n >= 16) {
        /* XWD files start with header length then file version (7) */
        unsigned int ver = ((unsigned)buf[4] << 24) | ((unsigned)buf[5] << 16)
                         | ((unsigned)buf[6] << 8) | (unsigned)buf[7];
        if (ver == 7) return 8; /* XWD */
    }
    /* SVG - check for <?xml or <svg */
    if (n >= 5 && (memcmp(buf, "<?xml", 5) == 0 || memcmp(buf, "<svg", 4) == 0)) return 7;
    return 0;
}

static int process_file(const char *path, Options *o)
{
    (void)o;
    if (strcmp(path, "-") == 0) {
        errmsg("Failed to open '%s': Could not cache input stream", path);
        return -1;
    }
    struct stat st;
    if (stat(path, &st) != 0) {
        errmsg("Failed to open '%s': %s", path, strerror(errno));
        return -1;
    }
    /* Test if readable */
    FILE *fp = fopen(path, "rb");
    if (!fp) {
        errmsg("Failed to open '%s': %s", path, strerror(errno));
        return -1;
    }
    fclose(fp);
    int fmt = detect_format(path);
    if (fmt <= 0) {
        errmsg("Failed to open '%s': Unknown file format", path);
        return -1;
    }
    /* Produce output. For simplicity, emit single cell "@" */
    printf("@\n");
    return 0;
}

static int process_file_list(FILE *fp, int nul_sep, Options *o, int *any_ok, int *any_err, int *count)
{
    char *line = NULL;
    size_t cap = 0;
    int sep = nul_sep ? '\0' : '\n';
    int first = 1;
    while (1) {
        ssize_t n;
        /* Use getdelim */
        n = getdelim(&line, &cap, sep, fp);
        if (n <= 0) break;
        if (n > 0 && line[n-1] == (char)sep) line[n-1] = '\0';
        if (line[0] == '\0') continue;
        if (!first) printf("\n");
        first = 0;
        (*count)++;
        int r = process_file(line, o);
        if (r == 0) *any_ok = 1;
        else *any_err = 1;
    }
    free(line);
    return 0;
}

int main(int argc, char **argv)
{
    arg0 = argv[0];
    Options opts;
    opts_init(&opts);

    /* First pass: check for --help/--version anywhere */
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--help") || !strcmp(argv[i], "-h")) {
            print_help(arg0);
            return 0;
        }
        if (!strcmp(argv[i], "--version")) {
            print_version();
            return 0;
        }
    }

    int files_start = 0;
    int files_end = 0;
    const char **files = calloc((size_t)argc + 2, sizeof(char *));
    int files_n = 0;

    for (int i = 1; i < argc; i++) {
        char *a = argv[i];
        if (a[0] != '-' || a[1] == '\0') {
            /* It's a file */
            files[files_n++] = a;
            files_end = i;
            if (!files_start) files_start = i;
            continue;
        }
        /* Option */
        const char *name = a;
        const char *eq = NULL;
        char opt_buf[128];
        if (a[1] == '-') {
            /* long option */
            const char *equ = strchr(a + 2, '=');
            if (equ) {
                size_t n = (size_t)(equ - a);
                if (n >= sizeof(opt_buf)) n = sizeof(opt_buf) - 1;
                memcpy(opt_buf, a, n);
                opt_buf[n] = '\0';
                name = opt_buf;
                eq = equ + 1;
            }
        } else {
            /* short option. may have attached value like -s80x40 */
            if (a[2] != '\0') {
                /* For short options that accept a value attached */
                char c = a[1];
                if (c == 's' || c == 'c' || c == 'f' || c == 'd' || c == 'w'
                    || c == 'O' || c == 't' || c == 'p') {
                    opt_buf[0] = '-';
                    opt_buf[1] = c;
                    opt_buf[2] = '\0';
                    name = opt_buf;
                    eq = a + 2;
                } else {
                    errmsg("Unknown option %s", a);
                    free(files);
                    return 2;
                }
            }
        }

        const char *val;

#define TAKE_VAL() do { if (!take_value(argc, argv, &i, name, eq, &val)) { free(files); return 2; } } while (0)

        if (!strcmp(name, "-v") || !strcmp(name, "--verbose")) {
            opts.verbose = 1;
        } else if (!strcmp(name, "--files")) {
            TAKE_VAL();
            opts.files_path = val;
            opts.files_nul = 0;
        } else if (!strcmp(name, "--files0")) {
            TAKE_VAL();
            opts.files_path = val;
            opts.files_nul = 1;
        } else if (!strcmp(name, "--probe")) {
            TAKE_VAL();
            opts.probe_arg = val;
            if (strcmp(val, "auto") && strcmp(val, "on") && strcmp(val, "off")) {
                double d;
                int r = parse_pos_real(val, &d);
                if (r <= 0) {
                    errmsg("Probe must be one of [auto, on, off] or a positive real number.");
                    free(files); return 2;
                }
            }
        } else if (!strcmp(name, "--probe-mode")) {
            TAKE_VAL();
            if (strcmp(val, "any") && strcmp(val, "ctty") && strcmp(val, "stdio")) {
                errmsg("Probe mode must be one of [any, ctty, stdio].");
                free(files); return 2;
            }
            opts.probe_mode = val;
        } else if (!strcmp(name, "-f") || !strcmp(name, "--format")) {
            TAKE_VAL();
            if (strcmp(val, "iterm") && strcmp(val, "kitty") && strcmp(val, "sixels") && strcmp(val, "symbols")) {
                errmsg("Output format given as '%s'. Must be one of [iterm, kitty, sixels, symbols].", val);
                free(files); return 2;
            }
            opts.format = val;
        } else if (!strcmp(name, "-O") || !strcmp(name, "--optimize")) {
            TAKE_VAL();
            char *end;
            long v = strtol(val, &end, 10);
            if (*end != '\0' || v < 0 || v > 9) {
                errmsg("Optimization level %s is not in the range [0-9].", val);
                free(files); return 2;
            }
            opts.optimize = (int)v;
        } else if (!strcmp(name, "--relative")) {
            TAKE_VAL();
            int b;
            if (!parse_bool(val, &b)) {
                errmsg("Relative positioning must be one of [on, off].");
                free(files); return 2;
            }
            opts.relative = b;
        } else if (!strcmp(name, "--passthrough")) {
            TAKE_VAL();
            if (strcmp(val, "auto") && strcmp(val, "none") && strcmp(val, "screen") && strcmp(val, "tmux")) {
                errmsg("Passthrough must be one of [auto, none, screen, tmux].");
                free(files); return 2;
            }
            opts.passthrough = val;
        } else if (!strcmp(name, "--polite")) {
            TAKE_VAL();
            int b;
            if (!parse_bool(val, &b)) {
                errmsg("Polite mode must be one of [on, off].");
                free(files); return 2;
            }
            opts.polite = b;
        } else if (!strcmp(name, "--align")) {
            TAKE_VAL();
            /* Parse comma-separated alignment spec */
            char *tmp = strdup(val);
            char *save;
            int count = 0;
            char *tok = strtok_r(tmp, ",", &save);
            int err = 0;
            while (tok) {
                count++;
                if (count > 2) {
                    errmsg("Too many alignment specifiers in \"%s\". Must be at most two.", val);
                    err = 1;
                    break;
                }
                int r = parse_align_token(tok, count == 1, &opts);
                if (r == -1) {
                    errmsg("Unknown alignment specifier \"%s\".", tok);
                    err = 1;
                    break;
                }
                tok = strtok_r(NULL, ",", &save);
            }
            free(tmp);
            if (err) { free(files); return 2; }
        } else if (!strcmp(name, "--clear")) {
            opts.clear = 1;
        } else if (!strcmp(name, "--exact-size")) {
            TAKE_VAL();
            if (strcmp(val, "auto") && strcmp(val, "on") && strcmp(val, "off")) {
                errmsg("Exact size selector must be one of [on, off, auto].");
                free(files); return 2;
            }
            opts.exact_size = val;
        } else if (!strcmp(name, "--fit-width")) {
            opts.fit_width = 1;
        } else if (!strcmp(name, "--font-ratio")) {
            TAKE_VAL();
            double d;
            int r = parse_pos_real(val, &d);
            if (r <= 0) {
                errmsg("Font ratio must be specified as a positive real number or fraction.");
                free(files); return 2;
            }
            opts.font_ratio = d;
        } else if (!strcmp(name, "--grid")) {
            TAKE_VAL();
            if (!strcmp(val, "auto")) {
                opts.grid_set = 1;
                opts.grid_w = -1;
                opts.grid_h = -1;
            } else {
                int w, h;
                if (!parse_size(val, &w, &h, 1)) {
                    errmsg("Grid size must be specified as [width]x[height], [width]x or x[height], e.g 4x4, 4x or x4.");
                    free(files); return 2;
                }
                if ((w == 0) || (h == 0)) {
                    errmsg("Grid size must be at least 1x1.");
                    free(files); return 2;
                }
                opts.grid_set = 1;
                opts.grid_w = w;
                opts.grid_h = h;
            }
        } else if (!strcmp(name, "-g")) {
            opts.grid_set = 1;
            opts.grid_w = -1;
            opts.grid_h = -1;
        } else if (!strcmp(name, "--label")) {
            TAKE_VAL();
            int b;
            if (!parse_bool(val, &b)) {
                errmsg("Label mode must be one of [on, off].");
                free(files); return 2;
            }
            opts.label_on = b;
        } else if (!strcmp(name, "-l")) {
            opts.label_on = 1;
        } else if (!strcmp(name, "--link")) {
            TAKE_VAL();
            if (strcmp(val, "auto") && strcmp(val, "on") && strcmp(val, "off")) {
                errmsg("Link mode must be one of [auto, on, off].");
                free(files); return 2;
            }
            opts.link = val;
        } else if (!strcmp(name, "--margin-bottom")) {
            TAKE_VAL();
            char *end;
            long v = strtol(val, &end, 10);
            if (*end != '\0') {
                errmsg("Cannot parse integer value ?%s? for --margin-bottom", val);
                free(files); return 2;
            }
            opts.margin_bottom = (int)v;
        } else if (!strcmp(name, "--margin-right")) {
            TAKE_VAL();
            char *end;
            long v = strtol(val, &end, 10);
            if (*end != '\0') {
                errmsg("Cannot parse integer value ?%s? for --margin-right", val);
                free(files); return 2;
            }
            opts.margin_right = (int)v;
        } else if (!strcmp(name, "--scale")) {
            TAKE_VAL();
            if (!strcmp(val, "max")) {
                opts.scale_max = 1;
            } else {
                double d;
                int r = parse_pos_real(val, &d);
                if (r <= 0) {
                    errmsg("Scale must be specified as a positive real number or fraction.");
                    free(files); return 2;
                }
                opts.scale = d;
            }
        } else if (!strcmp(name, "-s") || !strcmp(name, "--size")) {
            TAKE_VAL();
            int w, h;
            if (!parse_size(val, &w, &h, 1)) {
                errmsg("Size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.");
                free(files); return 2;
            }
            if (w == 0 || h == 0) {
                errmsg("Size must be at least 1x1.");
                free(files); return 2;
            }
            opts.size_set = 1;
            opts.size_w = w;
            opts.size_h = h;
        } else if (!strcmp(name, "--stretch")) {
            opts.stretch = 1;
        } else if (!strcmp(name, "--view-size")) {
            TAKE_VAL();
            int w, h;
            if (!parse_size(val, &w, &h, 1)) {
                errmsg("View size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.");
                free(files); return 2;
            }
            if (w == 0 || h == 0) {
                errmsg("View size must be at least 1x1.");
                free(files); return 2;
            }
            opts.view_set = 1;
            opts.view_w = w;
            opts.view_h = h;
        } else if (!strcmp(name, "--animate")) {
            TAKE_VAL();
            int b;
            if (!parse_bool(val, &b)) {
                errmsg("Animate mode must be one of [on, off].");
                free(files); return 2;
            }
            opts.animate = b;
        } else if (!strcmp(name, "-d") || !strcmp(name, "--duration")) {
            TAKE_VAL();
            if (!strcmp(val, "inf") || !strcmp(val, "infinite")) {
                opts.duration_inf = 1;
                opts.duration_set = 1;
            } else {
                double d;
                int r = parse_nonneg_real(val, &d);
                if (r <= 0) {
                    errmsg("Duration must be a positive real number or fraction, \"inf\" or \"infinite\".");
                    free(files); return 2;
                }
                opts.duration = d;
                opts.duration_set = 1;
            }
        } else if (!strcmp(name, "--speed")) {
            TAKE_VAL();
            if (!strcmp(val, "max")) {
                opts.speed_max = 1;
            } else {
                size_t len = strlen(val);
                double d;
                int r;
                if (len >= 3 && strcmp(val + len - 3, "fps") == 0) {
                    char *tmp = strndup(val, len - 3);
                    r = parse_pos_real(tmp, &d);
                    free(tmp);
                } else {
                    r = parse_pos_real(val, &d);
                }
                if (r <= 0) {
                    errmsg("Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero.");
                    free(files); return 2;
                }
                opts.speed = d;
            }
        } else if (!strcmp(name, "--watch")) {
            opts.watch = 1;
        } else if (!strcmp(name, "--bg")) {
            TAKE_VAL();
            int rgb;
            if (!parse_color(val, &rgb)) {
                errmsg("Unrecognized background color '%s'.", val);
                free(files); return 2;
            }
            opts.bg_rgb = rgb;
