    int first = 1;
    while (1) {
        ssize_t n;
        /* Use getdelim */
        n = getdelim(&line, &cap, sep, fp);
        if (n <= 0) break;
        if (n > 0 && line[n-1] == (char)sep) line[n-1] = '\0';
        if (line[0] == '\0') continue;
        if (!first) printf("\n");
        first = 0;
        (*count)++;
        int r = process_file(line, o);
        if (r == 0) *any_ok = 1;
        else *any_err = 1;
    }
    free(line);
    return 0;
}

