static int parse_bool(const char *s, int *out)
{
    if (!s) return 0;
    if (strcmp(s, "on") == 0 || strcmp(s, "1") == 0 || strcmp(s, "true") == 0 || strcmp(s, "yes") == 0) {
        *out = 1; return 1;
    }
    if (strcmp(s, "off") == 0 || strcmp(s, "0") == 0 || strcmp(s, "false") == 0 || strcmp(s, "no") == 0) {
        *out = 0; return 1;
    }
    return 0;
}

/* Parse a positive real, possibly given as fraction "a/b". Returns 1 on success,
 * 0 on parse failure, -1 if parsed but not strictly positive. */
static int parse_pos_real(const char *s, double *out)
{
    if (!s || !*s) return 0;
    char *end;
    double a = strtod(s, &end);
    if (end == s) return 0;
    if (*end == '/') {
        const char *s2 = end + 1;
        char *end2;
        double b = strtod(s2, &end2);
        if (end2 == s2 || *end2 != '\0') return 0;
        if (b == 0.0) return -1;
        a = a / b;
    } else if (*end != '\0') {
        return 0;
    }
    if (!(a > 0.0)) return -1;
    *out = a;
    return 1;
}

/* Similar but allows non-negative */
static int parse_nonneg_real(const char *s, double *out)
{
    if (!s || !*s) return 0;
    char *end;
    double a = strtod(s, &end);
    if (end == s) return 0;
    if (*end == '/') {
        const char *s2 = end + 1;
        char *end2;
        double b = strtod(s2, &end2);
        if (end2 == s2 || *end2 != '\0') return 0;
        if (b == 0.0) return -1;
        a = a / b;
    } else if (*end != '\0') {
        return 0;
    }
    if (!(a >= 0.0)) return -1;
    *out = a;
    return 1;
}

/* Parse "WxH", "Wx", "xH", or "W" (interpreted as WxW?) */
static int parse_size(const char *s, int *w, int *h, int allow_bare_dim)
{
    if (!s) return 0;
    const char *x = strchr(s, 'x');
    if (!x) {
        if (!allow_bare_dim) return 0;
        /* W only -> WxW? Actually --size "80" -> 80x(default). Use -1 for omitted */
        /* Actually chafa accepts a bare number for --size too, meaning width only */
        char *end;
        long v = strtol(s, &end, 10);
        if (*end != '\0' || v <= 0) return 0;
        *w = (int)v;
        *h = -1;
        return 1;
    }
    /* Parse left side */
    if (x == s) {
        *w = -1;
    } else {
        char buf[64];
        size_t n = (size_t)(x - s);
        if (n >= sizeof(buf)) return 0;
        memcpy(buf, s, n);
        buf[n] = '\0';
        char *end;
        long v = strtol(buf, &end, 10);
        if (*end != '\0' || v < 0) return 0;
        *w = (int)v;
    }
    /* Parse right side */
    const char *rhs = x + 1;
    if (*rhs == '\0') {
        *h = -1;
    } else {
        char *end;
        long v = strtol(rhs, &end, 10);
        if (*end != '\0' || v < 0) return 0;
        *h = (int)v;
    }
    return 1;
}

