/* Matches: --name=value, --name value, -x value, -xvalue. */
static int take_value(int argc, char **argv, int *ip, const char *optname_for_error,
                      const char *eq, const char **out_value)
{
    if (eq) {
        *out_value = eq;
        return 1;
    }
    int i = *ip;
    if (i + 1 >= argc) {
        errmsg("Missing argument for %s", optname_for_error);
